
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRAN;

-- -----------------------------------------------------------------------------
-- Clear existing data from all user tables before replaying inserts.
-- -----------------------------------------------------------------------------
DECLARE @wipeSql NVARCHAR(MAX) = N'';

-- Disable FK/check constraints.
SELECT @wipeSql = @wipeSql +
	N'ALTER TABLE ' + QUOTENAME(s.name) + N'.' + QUOTENAME(t.name) + N' NOCHECK CONSTRAINT ALL;' + CHAR(13) + CHAR(10)
FROM sys.tables t
JOIN sys.schemas s
	ON s.schema_id = t.schema_id
WHERE t.is_ms_shipped = 0;

EXEC sp_executesql @wipeSql;

-- Delete table data.
SET @wipeSql = N'';
SELECT @wipeSql = @wipeSql +
	N'DELETE FROM ' + QUOTENAME(s.name) + N'.' + QUOTENAME(t.name) + N';' + CHAR(13) + CHAR(10)
FROM sys.tables t
JOIN sys.schemas s
	ON s.schema_id = t.schema_id
WHERE t.is_ms_shipped = 0;

EXEC sp_executesql @wipeSql;

-- Re-enable constraints.
SET @wipeSql = N'';
SELECT @wipeSql = @wipeSql +
	N'ALTER TABLE ' + QUOTENAME(s.name) + N'.' + QUOTENAME(t.name) + N' CHECK CONSTRAINT ALL;' + CHAR(13) + CHAR(10)
FROM sys.tables t
JOIN sys.schemas s
	ON s.schema_id = t.schema_id
WHERE t.is_ms_shipped = 0;

EXEC sp_executesql @wipeSql;

