INSERT INTO [dbo].[company_name_type] ([company_name_type_id], [company_name_type], [company_name_type_description]) VALUES (1,'Primary','The official name of the company. There can be only one primary either romanized or localized.');
INSERT INTO [dbo].[company_name_type] ([company_name_type_id], [company_name_type], [company_name_type_description]) VALUES (2,'Secondary','Additional names. Primarily used to improve matching.');
INSERT INTO [dbo].[company_name_type] ([company_name_type_id], [company_name_type], [company_name_type_description]) VALUES (3,'Standardized','Cleaned via string replacement process. Ideal for simple name matching.');
INSERT INTO [dbo].[company_name_type] ([company_name_type_id], [company_name_type], [company_name_type_description]) VALUES (4,'Acronym','Based on the user or manual entries if there are at least three words.');
INSERT INTO [dbo].[company_name_type] ([company_name_type_id], [company_name_type], [company_name_type_description]) VALUES (5,'Split','Individual words. Useful for matching names that can be arranged in a different order.');
INSERT INTO [dbo].[company_name_type] ([company_name_type_id], [company_name_type], [company_name_type_description]) VALUES (6,'Soundex','The individual words processed the Soundex phonetic algorithm.');
INSERT INTO [dbo].[company_name_type] ([company_name_type_id], [company_name_type], [company_name_type_description]) VALUES (7,'First','The left-most characters of the name.');
