INSERT INTO [dbo].[spy_alert] ([alert_id], [title], [description], [link], [start_date], [end_date], [sub_status], [expire_begin], [expire_end], [reg_status], [language_id], [alert_product_version_id], [version_compare_id], [insert_date], [insert_by], [modified_date], [modified_by], [alert_status]) VALUES (3,' Register your Spy Sweeper Software','Our records show that your Spy Sweeper software isn''t registered. You need to register your software to receive information about product updates and releases.     In addition, registration is required to access our free customer support, which you are eligible to receive during the entire length of your subscription.    Click the link below to access the registration page.  ','http://www.webroot.com/oemregister.htm','2006-08-29T00:00:00','2006-08-29T00:00:00',2,0,0,3,25,5,1,'2006-08-29T16:49:06.330','jkindblade','2006-08-29T16:49:06.330','jkindblade',1);
INSERT INTO [dbo].[spy_alert] ([alert_id], [title], [description], [link], [start_date], [end_date], [sub_status], [expire_begin], [expire_end], [reg_status], [language_id], [alert_product_version_id], [version_compare_id], [insert_date], [insert_by], [modified_date], [modified_by], [alert_status]) VALUES (4,'Your Spy Sweeper subscription has expired and Your PC is at Risk!','Do you bank online? Shop online? Download music? These activities might be dangerous to the health of your PC and your credit score.     Because your Spy Sweeper subscription ended, your PC is at risk of dangerous spyware infection, which can steal your information and damage your PC.     Renew your subscription today. ','https://www.webroot.com/consumer/products/renew.html','2006-12-22T00:00:00','2006-12-22T00:00:00',3,0,0,1,25,5,1,'2006-12-22T15:27:37.110','jkindblade','2006-12-22T15:27:37.110','jkindblade',1);
